CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, owner_id uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_owner ON public.organizations FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE DEFAULT auth.uid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), full_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profile_write ON public.profiles FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()));
CREATE FUNCTION public.owns_org(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organizations WHERE id=org AND owner_id=auth.uid()) $$;
GRANT EXECUTE ON FUNCTION public.owns_org(uuid) TO authenticated;
CREATE TABLE public.ai_agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), name text NOT NULL, business_type text NOT NULL DEFAULT 'Other', description text, system_prompt text, greeting text, voice text NOT NULL DEFAULT '21m00Tcm4TlvDq8ikWAM', language text NOT NULL DEFAULT 'en', vapi_assistant_id text UNIQUE, status text NOT NULL DEFAULT 'inactive', role text, personality text, avatar text, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ai_agents TO authenticated; GRANT ALL ON public.ai_agents TO service_role;
ALTER TABLE public.ai_agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY agents_org ON public.ai_agents FOR ALL TO authenticated USING(public.owns_org(organization_id)) WITH CHECK(public.owns_org(organization_id));
CREATE TABLE public.knowledge_base (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), agent_id uuid, title text NOT NULL, content text, file_name text, file_type text, file_url text, source_type text NOT NULL DEFAULT 'text', status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(agent_id,organization_id) REFERENCES public.ai_agents(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.knowledge_base TO authenticated; GRANT ALL ON public.knowledge_base TO service_role;
ALTER TABLE public.knowledge_base ENABLE ROW LEVEL SECURITY;
CREATE POLICY kb_org ON public.knowledge_base FOR ALL TO authenticated USING(public.owns_org(organization_id)) WITH CHECK(public.owns_org(organization_id));
CREATE TABLE public.phone_numbers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), agent_id uuid, phone_number text, provider text NOT NULL DEFAULT 'vapi', direction text NOT NULL DEFAULT 'both', status text NOT NULL DEFAULT 'not_connected', vapi_phone_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id), FOREIGN KEY(agent_id,organization_id) REFERENCES public.ai_agents(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.phone_numbers TO authenticated; GRANT ALL ON public.phone_numbers TO service_role;
ALTER TABLE public.phone_numbers ENABLE ROW LEVEL SECURITY;
CREATE POLICY phones_org ON public.phone_numbers FOR ALL TO authenticated USING(public.owns_org(organization_id)) WITH CHECK(public.owns_org(organization_id));
CREATE TABLE public.leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), agent_id uuid, call_id uuid, name text NOT NULL, phone text, email text, interested_in text, source text, status text NOT NULL DEFAULT 'new', notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id), FOREIGN KEY(agent_id,organization_id) REFERENCES public.ai_agents(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY leads_org ON public.leads FOR ALL TO authenticated USING(public.owns_org(organization_id)) WITH CHECK(public.owns_org(organization_id));
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), agent_id uuid, lead_id uuid, customer_name text NOT NULL, phone text, email text, purpose text, scheduled_date date NOT NULL, scheduled_time text NOT NULL, status text NOT NULL DEFAULT 'scheduled', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id), FOREIGN KEY(agent_id,organization_id) REFERENCES public.ai_agents(id,organization_id), FOREIGN KEY(lead_id,organization_id) REFERENCES public.leads(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.appointments TO authenticated; GRANT ALL ON public.appointments TO service_role;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointments_org ON public.appointments FOR ALL TO authenticated USING(public.owns_org(organization_id)) WITH CHECK(public.owns_org(organization_id));
CREATE TABLE public.calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), agent_id uuid, phone_number_id uuid, caller_number text, caller_name text, direction text NOT NULL DEFAULT 'inbound', duration_seconds integer DEFAULT 0, status text NOT NULL DEFAULT 'completed', outcome text, recording_url text, transcript text, summary text, tools_used jsonb DEFAULT '[]', lead_id uuid, appointment_id uuid, started_at timestamptz DEFAULT now(), ended_at timestamptz, vapi_call_id text UNIQUE, handoff_status text DEFAULT 'ai_handling', UNIQUE(id,organization_id), FOREIGN KEY(agent_id,organization_id) REFERENCES public.ai_agents(id,organization_id), FOREIGN KEY(phone_number_id,organization_id) REFERENCES public.phone_numbers(id,organization_id), FOREIGN KEY(lead_id,organization_id) REFERENCES public.leads(id,organization_id), FOREIGN KEY(appointment_id,organization_id) REFERENCES public.appointments(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.calls TO authenticated; GRANT ALL ON public.calls TO service_role;
ALTER TABLE public.calls ENABLE ROW LEVEL SECURITY;
CREATE POLICY calls_org ON public.calls FOR ALL TO authenticated USING(public.owns_org(organization_id)) WITH CHECK(public.owns_org(organization_id));
ALTER TABLE public.leads ADD CONSTRAINT leads_call_tenant FOREIGN KEY(call_id,organization_id) REFERENCES public.calls(id,organization_id);
CREATE TABLE public.org_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL UNIQUE REFERENCES public.organizations(id), industry text, email text, phone text, website text, timezone text DEFAULT 'UTC', default_language text DEFAULT 'en', default_voice text, default_greeting text, default_handoff_rules jsonb DEFAULT '{}', human_handoff_phone text, handoff_conditions jsonb DEFAULT '[]', business_hours jsonb DEFAULT '{}', fallback_behavior text DEFAULT 'take_message', notifications jsonb DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.org_settings TO authenticated; GRANT ALL ON public.org_settings TO service_role;
ALTER TABLE public.org_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_org ON public.org_settings FOR ALL TO authenticated USING(public.owns_org(organization_id)) WITH CHECK(public.owns_org(organization_id));
CREATE TABLE public.migration_identities (original_user_id uuid PRIMARY KEY, verified_email text NOT NULL UNIQUE, cloud_user_id uuid UNIQUE, import_verified_at timestamptz);
GRANT ALL ON public.migration_identities TO service_role;
ALTER TABLE public.migration_identities ENABLE ROW LEVEL SECURITY;
CREATE INDEX agents_org_idx ON public.ai_agents(organization_id); CREATE INDEX calls_org_idx ON public.calls(organization_id,started_at); CREATE INDEX leads_org_idx ON public.leads(organization_id); CREATE INDEX knowledge_org_idx ON public.knowledge_base(organization_id); CREATE INDEX appointments_org_idx ON public.appointments(organization_id,scheduled_date);
CREATE FUNCTION public.bootstrap_organization(business_name text,display_name text) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE org_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT organization_id INTO org_id FROM public.profiles WHERE user_id=auth.uid(); IF org_id IS NOT NULL THEN RETURN org_id; END IF; IF length(trim(business_name))<1 THEN RAISE EXCEPTION 'Business name required'; END IF; INSERT INTO public.organizations(name,owner_id) VALUES(trim(business_name),auth.uid()) RETURNING id INTO org_id; INSERT INTO public.profiles(user_id,organization_id,full_name) VALUES(auth.uid(),org_id,display_name); INSERT INTO public.org_settings(organization_id) VALUES(org_id); RETURN org_id; END $$;
REVOKE ALL ON FUNCTION public.bootstrap_organization(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bootstrap_organization(text,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.calls;